mapper.update:
UPDATE reservation
SET service_id = #{serviceId},
    reservation_start = #{reservationStart},
    request_memo = #{requestMemo}
WHERE id = #{id}

UPDATE reservation
SET status = #{status}
WHERE id = #{id}

UPDATE reservation
SET calendar_event_id = #{calendarEventId}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM reservation r
INNER JOIN service_item s ON s.id = r.service_id
WHERE r.status IN ('REQUESTED', 'CONFIRMED')
  AND r.reservation_start  <  #{end}
  AND DATE_ADD(r.reservation_start, INTERVAL s.duration_minutes MINUTE)  >  #{start}

  AND r.id != #{excludeId}

SELECT COUNT(*)
FROM reservation r
INNER JOIN service_item s ON s.id = r.service_id
WHERE r.status IN ('REQUESTED', 'CONFIRMED')
  AND r.reservation_start  <  #{end}
  AND DATE_ADD(r.reservation_start, INTERVAL s.duration_minutes MINUTE)  >  #{start}

  AND r.id != #{excludeId}

FOR UPDATE
